-- Help & FAQ: questions and answers about Rahbar, shown in the app to the people they apply to (audience: ALL,
-- STAFF, SPONSORS or STUDENTS). on_website puts one on the biharanjuman.com FAQ page; off unless switched on.
-- Editing needs the FAQS permission (Roles & Responsibilities).
CREATE TABLE IF NOT EXISTS faqs (
  id BIGINT NOT NULL AUTO_INCREMENT,
  category VARCHAR(80) NOT NULL,
  audience VARCHAR(10) NOT NULL DEFAULT 'ALL',
  question VARCHAR(300) NOT NULL,
  answer TEXT NOT NULL,
  on_website BOOLEAN NOT NULL DEFAULT FALSE,
  active BOOLEAN NOT NULL DEFAULT TRUE,
  display_order INT NOT NULL DEFAULT 0,
  created_by BIGINT NULL, updated_by BIGINT NULL, created_at DATETIME(6) NULL, updated_at DATETIME(6) NULL,
  PRIMARY KEY (id),
  KEY idx_faqs_order (display_order)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Application Administrator (2) and Office Coordinator (8) manage the FAQ; the Super Admin always may.
UPDATE roles SET permissions = CONCAT_WS(',', NULLIF(permissions, ''), 'FAQS:VIEW', 'FAQS:EDIT')
 WHERE role_id IN (2, 8) AND FIND_IN_SET('FAQS:EDIT', COALESCE(permissions, '')) = 0;

