INSERT INTO faqs (category, audience, question, answer, on_website, active, display_order) VALUES
  ('Getting started', 'ALL', 'What is Rahbar?', 'Rahbar is Bihar Anjuman''s system for its education work: scholarship applications, students and their sponsors, payments and installments, progress reports, chapters and coaching centres (RCC), Rahbar-e-Banaat, mentoring, and the content of the biharanjuman.com website.', FALSE, TRUE, 10),
  ('Getting started', 'ALL', 'How do I sign in?', 'Sign in with your email address or phone number and your password. If an admin created your account, you received a temporary password: you will be asked to choose your own password the first time you sign in.', FALSE, TRUE, 20),
  ('Getting started', 'ALL', 'I forgot my password. What do I do?', 'Use "Forgot password" on the sign-in page. We email you a code; enter it with your new password. The code expires after a short time and after a few wrong tries, so ask for a new one if needed. If you have no email address on file, contact the office.', FALSE, TRUE, 30),
  ('Getting started', 'ALL', 'Why do I see a banner asking me to add my email address?', 'We have no real email address for you (none, or a placeholder ending in @rahbar.com). Without one you miss reminders, payment notices and sign-in help. Add your email in My profile.', FALSE, TRUE, 40),
  ('Getting started', 'ALL', 'Where do I change my name, email or phone number?', 'Open the menu under your name and choose My profile. Each email address and phone number can belong to one account only, so you cannot use one that another account already has.', FALSE, TRUE, 50),
  ('Getting started', 'ALL', 'I have more than one role. How do I switch between them?', 'One person has one account, which can hold several roles (for example Super Admin and Sponsor). Your main role decides the screen you start on. In the menu under your name, "Switch to" opens the admin area or a portal (Sponsor, Student, Coordinator, Convenor), and "View as" shows the app exactly as one of your staff roles sees it. My profile lists all your roles.', FALSE, TRUE, 60),
  ('Getting started', 'ALL', 'Why can''t I see a menu item that a colleague can see?', 'Every role sees the screens given to it in Roles & Responsibilities. Ask the Super Admin if you need access. Chapter leads and RCC leads only see the records of their own chapter or coaching centre.', FALSE, TRUE, 70),
  ('Getting started', 'ALL', 'Where do I find my notifications?', 'The bell at the top of the page shows your notifications (new progress reports, payments, notes and so on). Important ones are also emailed to you.', FALSE, TRUE, 80),
  ('Students', 'STUDENTS', 'How do I upload my progress report?', 'Open Progress in your student portal, enter your marks, the year and semester, and upload your marksheet. The office reviews it, and your sponsor is told that a new report is there.', FALSE, TRUE, 90),
  ('Students', 'STUDENTS', 'When is my next progress report due?', 'Your dashboard shows the next due date and anything overdue. You also get an email reminder before it is due.', FALSE, TRUE, 100),
  ('Students', 'STUDENTS', 'How do I confirm that I received a payment?', 'Open Payments in your student portal and upload proof of how the money was spent (for example the fee receipt) against that payment. Your sponsor is told when you do.', FALSE, TRUE, 110),
  ('Students', 'STUDENTS', 'Can I write to my sponsor?', 'Yes. Open "Write to my Sponsor", choose an update or a thank-you note and write a few lines. The office reads it first and then passes it on; you can see whether it was sent or returned (with the reason).', FALSE, TRUE, 120),
  ('Students', 'STUDENTS', 'Can I see my payment schedule?', 'Yes. Payments in your student portal shows every installment from your sponsor with its due date and whether it was paid.', FALSE, TRUE, 130),
  ('Students', 'STUDENTS', 'What happens when I graduate?', 'The office marks you as Graduated. Your Alumni Profile then opens, where you can share what you do now (job, higher studies, ...) and agree to be contacted, for example to mentor current students. Your sponsor is told that you graduated.', FALSE, TRUE, 140),
  ('Sponsors', 'SPONSORS', 'How do I see what I need to pay?', 'Open Payments. It lists every installment of all your students: "Due now" shows what to pay now (overdue and due), "Next payment" the next due date and amount, and you can filter by student, status and year.', FALSE, TRUE, 150),
  ('Sponsors', 'SPONSORS', 'How do I record a payment I made?', 'On Payments, click "Pay now" on the installment, enter the date and amount and upload the bank receipt. The student''s bank details are shown in the same window.', FALSE, TRUE, 160),
  ('Sponsors', 'SPONSORS', 'Can I get a receipt or a yearly statement?', 'Yes. Every paid installment has a "Rahbar receipt (PDF)". The Statement button gives your yearly statement (PDF), and Excel downloads your payment history for a year or for all years.', FALSE, TRUE, 170),
  ('Sponsors', 'SPONSORS', 'Can I get reminders in my own calendar?', 'Yes. "Add to calendar" on the Payments page downloads your upcoming due dates; open the file to add them to Google, Apple or Outlook calendar, with a reminder three days before each date. You also get reminder emails from Rahbar.', FALSE, TRUE, 180),
  ('Sponsors', 'SPONSORS', 'How do I know how my student is doing?', 'Your dashboard shows a card for each student: course, institution, current semester, expected completion, study status, the latest progress report and whether the proof for your last payment came in. You also get an email when they upload a progress report or spending proof, and when they graduate.', FALSE, TRUE, 190),
  ('Sponsors', 'SPONSORS', 'What does "No news for a while" mean on my student''s card?', 'There has been no progress report or payment for that student for about four months. The office can follow up with the student.', FALSE, TRUE, 200),
  ('Sponsors', 'SPONSORS', 'Why can''t I see my student''s phone number or address?', 'To protect students, sponsors see their study information only: course, progress, payments and notes the student wrote to you (checked by the office).', FALSE, TRUE, 210),
  ('Sponsors', 'SPONSORS', 'My student moved to another sponsor. What do I still see?', 'They appear under Past Students on your dashboard, with the period you sponsored them and what you paid. Their payments and progress reports from your period stay visible to you.', FALSE, TRUE, 220),
  ('Payments', 'STAFF', 'How are a student''s installments created?', 'When a student is mapped to a sponsor, Rahbar builds the installments from the course''s number of semesters, the Payment Config of the student''s session year and the student''s payment start date. Payment Records lists all installments; a student''s own list is in the Student Directory.', FALSE, TRUE, 230),
  ('Payments', 'STAFF', 'What do Due, Overdue and Upcoming mean?', 'Paid has a recorded payment. Overdue: the due date has passed and it is unpaid. Due: the due date is near (the "show as due" days in Payment Config, 30 by default). Upcoming (Not Due): later than that.', FALSE, TRUE, 240),
  ('Payments', 'STAFF', 'When are payment reminders sent?', 'Automatically every morning: once for each overdue installment and once when the next installment becomes due. Payment Dues has "Send reminders now" to send any that haven''t gone out yet.', FALSE, TRUE, 250),
  ('Payments', 'STAFF', 'How do I record a payment for a sponsor?', 'In Payment Records, click "Record payment" on the installment and enter the date, amount and (optionally) the receipt.', FALSE, TRUE, 260),
  ('Office & admin', 'STAFF', 'What is a student''s study status?', 'Studying, On hold (payment dues continue but no reminders), Graduated or Dropped out (no more dues or reminders). Change it on the student''s Study tab in the Student Directory; the history is kept.', FALSE, TRUE, 270),
  ('Office & admin', 'STAFF', 'How do I search the Student Directory?', 'Every word you type must match somewhere: Ref ID, name, email, phone, sponsor, chapter, institution, course, study status or status (for example "graduated patna"). Use the filters for chapter, study status, status, sponsor, institution and course.', FALSE, TRUE, 280),
  ('Office & admin', 'STAFF', 'How do I give someone another role?', 'In Admin > Users, open the person and tick the role under "Also has these roles". Do not make a second account for the same person. Only a Super Admin can give or remove the Super Admin role.', FALSE, TRUE, 290),
  ('Office & admin', 'STAFF', 'Someone has two accounts. How do I fix it?', 'Data Quality lists "Same person, two accounts?" and "Possible duplicate students". The Super Admin can merge the second account into the one to keep: it gets both roles and everything that belongs to the person, and the other account is deactivated, never deleted.', FALSE, TRUE, 300),
  ('Office & admin', 'STAFF', 'What can a Chapter Lead or RCC Lead see?', 'Only the records of their own chapter or coaching centre, and only the screens their role allows. Their account must be linked to the chapter or centre in Admin > Users, otherwise they see nothing (Data Quality and My profile warn about it).', FALSE, TRUE, 310),
  ('Office & admin', 'STAFF', 'What does Data Quality check?', 'Missing or inconsistent data, such as students without a course or sponsor, leads without a chapter, possible duplicates and payment set-up gaps. Each check links to the screen where it is fixed.', FALSE, TRUE, 320),
  ('Office & admin', 'STAFF', 'How do I approve a note a student wrote to their sponsor?', 'Open Students > Notes to Sponsors. Check the note (no phone numbers, addresses or requests for money outside Rahbar), then Approve so the sponsor sees it and gets an email, or Return it with a reason for the student.', FALSE, TRUE, 330),
  ('Office & admin', 'STAFF', 'How does Mentoring work?', 'Students > Mentoring pairs scholarship students with volunteers who offered to mentor or tutor and with graduates who agreed to be contacted. "Find a mentor" ranks people by the fields they share with the student''s course, the same chapter and how many students they already have.', FALSE, TRUE, 340),
  ('Office & admin', 'STAFF', 'What is Sponsor Follow-up?', 'Sponsors & Payments > Sponsor Follow-up lists sponsors who stopped paying and sponsors with no student now. Log a call or note, or send a personal email; a sponsor contacted in the last seven days is skipped unless you insist.', FALSE, TRUE, 350),
  ('Office & admin', 'STAFF', 'Who can read a document?', 'Each document in Administration > Documents is either for everyone or for chosen roles. People who edit documents see all of them. In a portal (for example the Sponsor portal) only the documents for that role are shown.', FALSE, TRUE, 360),
  ('Office & admin', 'STAFF', 'How do I download a report?', 'Open Reports, choose the report (and dates where asked) and download it as CSV, Excel or PDF, or view it on screen. Some reports need extra access (for example Alumni or Volunteers), and chapter and RCC leads get only their own students.', FALSE, TRUE, 370),
  ('Office & admin', 'STAFF', 'How do the income and expense figures reach the website?', 'Administration > Income & Expenses keeps the books. Publishing a year shows its totals on the biharanjuman.com page "Where the money goes"; nothing about individual people is published.', FALSE, TRUE, 380),
  ('Programmes', 'ALL', 'What is Rahbar-e-Banaat?', 'Rahbar-e-Banaat is Bihar Anjuman''s school-cum-madarsa for girls. In Rahbar it has its own menu for admissions, classes, fees, attendance, exams and report cards, Quran / Hifz progress and the hostel.', FALSE, TRUE, 390),
  ('Programmes', 'ALL', 'What are RCC coaching centres?', 'Rahbar Coaching Centres prepare students for exams and admissions. Each centre has an incharge; RCC leads see and add the students of their own centre.', FALSE, TRUE, 400),
  ('Programmes', 'ALL', 'How can I sponsor a student?', 'Sign up on biharanjuman.com (Volunteer with us, "sponsor a student") or contact the office. Once you are registered, the office maps a student to you and you see their payment schedule in your Sponsor portal.', FALSE, TRUE, 410),
  ('Programmes', 'ALL', 'How can I volunteer, mentor or tutor?', 'Fill in "Volunteer with us" on biharanjuman.com and choose how you would like to help. The office contacts you and can pair you with a student who studies in your field.', FALSE, TRUE, 420),
  ('Website & FAQ', 'STAFF', 'How is the biharanjuman.com website updated?', 'Admin > Website holds the posts, news and events, success stories, gallery, directory, projects and pages. Who may write, edit or publish is set in Roles & Responsibilities.', FALSE, TRUE, 430),
  ('Website & FAQ', 'STAFF', 'Who can add or change these FAQs?', 'Anyone whose role has "FAQ" edit access in Roles & Responsibilities (by default the Super Admin, Application Administrator and Office Coordinator). Each FAQ says who sees it in Rahbar, and "Show on biharanjuman.com" puts it on the website''s FAQ page (off unless switched on).', FALSE, TRUE, 440);
